record User(String name) {}

AtomicReference<User> ref = new AtomicReference<>(new User("Aditya"));
boolean r1 = ref.compareAndSet(new User("Aditya"), new User("Rohit"));
User current = ref.get();
boolean r2 = ref.compareAndSet(current, new User("Rohit"));
System.out.println(r1 + " " + r2 + " " + ref.get().name());

class SeatBooking {
    AtomicReference<String> seat = new AtomicReference<>(new String("EMPTY"));

    boolean bookSeat(String name) {
        String currentValue = seat.get();
        if (!currentValue.equals("EMPTY")) {
            return false;
        }
        return seat.compareAndSet("EMPTY", name);
    }
}
